INSERT INTO src_locator(source_work_id,source_artifact_id,locator_type,heading_path,display_citation)
SELECT a.source_work_id,a.source_artifact_id,'heading','Refereeing the Game > Improvisation > Improvisational Preparation',CASE w.work_code WHEN 'cepheus-engine.ogn' THEN 'Cepheus Engine SRD, Improvisational Preparation' ELSE 'Cepheus Engine v9.1, Improvisational Preparation' END
FROM src_artifact a JOIN src_work w USING(source_work_id) WHERE (w.work_code='cepheus-engine.github-v9.1' AND a.source_uri='src/book3/refereeing-the-game.md') OR (w.work_code='cepheus-engine.ogn' AND a.source_uri='https://cepheus-srd.opengamingnetwork.com/cepheus-engine-srd/cepheus-engine-refereeing-the-game/') ON CONFLICT DO NOTHING;
WITH p AS(SELECT content_package_id FROM sys_content_package WHERE package_code='cepheus-engine') INSERT INTO rule_rule(content_package_id,rule_code,name,rule_category,rule_status,description) SELECT content_package_id,'referee.structured-scene-preparation','Structured Scene Preparation','encounter','approved','Agreed application convention: reusable scene blueprints preserve authoritative facts while narration remains generated and flexible.' FROM p;
INSERT INTO src_record_provenance(rule_id,content_package_id,source_locator_id,provenance_class,is_primary_citation) SELECT r.rule_id,r.content_package_id,l.source_locator_id,'agreed_addition',w.work_code='cepheus-engine.ogn' FROM rule_rule r CROSS JOIN src_locator l JOIN src_work w USING(source_work_id) WHERE r.rule_code='referee.structured-scene-preparation' AND l.heading_path='Refereeing the Game > Improvisation > Improvisational Preparation' AND w.work_code IN('cepheus-engine.ogn','cepheus-engine.github-v9.1');

