DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''create_scene_snapshot'' OR ')); END $$;
CREATE TABLE camp_scene_snapshot(scene_snapshot_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,public_id uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,campaign_id bigint NOT NULL REFERENCES camp_campaign,scene_template_code text NOT NULL REFERENCES rule_scene_template,location_id bigint,encounter_id bigint,journey_id bigint,scene_reference text NOT NULL CHECK(btrim(scene_reference)<>''),created_by_reference text NOT NULL CHECK(btrim(created_by_reference)<>''),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(scene_snapshot_id,campaign_id),FOREIGN KEY(location_id,campaign_id) REFERENCES loc_location(location_id,campaign_id),FOREIGN KEY(encounter_id,campaign_id) REFERENCES enc_encounter(encounter_id,campaign_id),FOREIGN KEY(journey_id,campaign_id) REFERENCES journey_journey(journey_id,campaign_id),CHECK(num_nonnulls(location_id,encounter_id,journey_id)<=1));
CREATE TABLE camp_scene_fact(scene_snapshot_id bigint NOT NULL,campaign_id bigint NOT NULL,slot_code text NOT NULL,fact_value text NOT NULL CHECK(btrim(fact_value)<>''),source_reference text CHECK(source_reference IS NULL OR btrim(source_reference)<>''),PRIMARY KEY(scene_snapshot_id,slot_code),FOREIGN KEY(scene_snapshot_id,campaign_id) REFERENCES camp_scene_snapshot(scene_snapshot_id,campaign_id));
CREATE TABLE cmd_scene_snapshot_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command,scene_snapshot_id bigint NOT NULL UNIQUE,campaign_id bigint NOT NULL REFERENCES camp_campaign,scene_template_code text NOT NULL REFERENCES rule_scene_template,fact_count smallint NOT NULL CHECK(fact_count>0),FOREIGN KEY(scene_snapshot_id,campaign_id) REFERENCES camp_scene_snapshot(scene_snapshot_id,campaign_id));
CREATE FUNCTION enc_validate_scene_snapshot_receipt() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE actual_template text;actual_count integer;missing integer;unknown integer;
BEGIN SELECT scene_template_code INTO STRICT actual_template FROM camp_scene_snapshot WHERE scene_snapshot_id=NEW.scene_snapshot_id;SELECT count(*) INTO actual_count FROM camp_scene_fact WHERE scene_snapshot_id=NEW.scene_snapshot_id;SELECT count(*) INTO missing FROM rule_scene_template_slot s WHERE s.scene_template_code=actual_template AND s.required AND NOT EXISTS(SELECT 1 FROM camp_scene_fact f WHERE f.scene_snapshot_id=NEW.scene_snapshot_id AND f.slot_code=s.slot_code);SELECT count(*) INTO unknown FROM camp_scene_fact f WHERE f.scene_snapshot_id=NEW.scene_snapshot_id AND NOT EXISTS(SELECT 1 FROM rule_scene_template_slot s WHERE s.scene_template_code=actual_template AND s.slot_code=f.slot_code);
 IF actual_template<>NEW.scene_template_code OR actual_count<>NEW.fact_count OR missing>0 OR unknown>0 THEN RAISE EXCEPTION 'Scene snapshot does not satisfy its structured template' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER cmd_scene_snapshot_receipt_valid BEFORE INSERT ON cmd_scene_snapshot_receipt FOR EACH ROW EXECUTE FUNCTION enc_validate_scene_snapshot_receipt();
CREATE FUNCTION enc_reject_sealed_scene_mutation() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE snapshot bigint;BEGIN snapshot:=OLD.scene_snapshot_id;IF EXISTS(SELECT 1 FROM cmd_scene_snapshot_receipt WHERE scene_snapshot_id=snapshot) THEN RAISE EXCEPTION 'Sealed scene snapshot is immutable' USING ERRCODE='55000';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER camp_scene_snapshot_immutable BEFORE UPDATE OR DELETE ON camp_scene_snapshot FOR EACH ROW EXECUTE FUNCTION enc_reject_sealed_scene_mutation();
CREATE TRIGGER camp_scene_fact_immutable BEFORE UPDATE OR DELETE ON camp_scene_fact FOR EACH ROW EXECUTE FUNCTION enc_reject_sealed_scene_mutation();
CREATE TRIGGER cmd_scene_snapshot_receipt_immutable BEFORE UPDATE OR DELETE ON cmd_scene_snapshot_receipt FOR EACH ROW EXECUTE FUNCTION enc_reject_social_content_selection_mutation();
